def count_lowercase_letters(s):
    """
    Returns a dictionary counting the occurrence of each lowercase letter in the given string.
    Whitespace characters and punctuation marks are excluded from being counted.
    """
    from string import ascii_lowercase

    # Initialize a dictionary with each lowercase letter set to 0
    letter_counts = {letter: 0 for letter in ascii_lowercase}

    # Increment counts for each lowercase letter in the string
    for char in s:
        if char in ascii_lowercase:
            letter_counts[char] += 1

    # Remove from dictionary letters that did not appear in the string
    letter_counts = {k: v for k, v in letter_counts.items() if v > 0}

    return letter_counts
